#!/usr/bin/env node
// One schema for both apps: src/lib/database.types.ts (generated by
// `npm run db:types`) is copied to web/src/lib/database.types.ts.
//
//   node scripts/sync-db-types.mjs          write the web copy
//   node scripts/sync-db-types.mjs --check  fail if the copies differ
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const app = join(root, 'src/lib/database.types.ts');
const web = join(root, 'web/src/lib/database.types.ts');

const source = readFileSync(app, 'utf8');
let current = null;
try {
  current = readFileSync(web, 'utf8');
} catch {
  // Not written yet.
}

if (process.argv.includes('--check')) {
  if (current !== source) {
    console.error('web/src/lib/database.types.ts is out of date. Run `npm run db:types` (or `npm run sync:db-types`).');
    process.exit(1);
  }
  console.log('Database types match in both apps.');
} else if (current === source) {
  console.log('web/src/lib/database.types.ts is already up to date.');
} else {
  writeFileSync(web, source);
  console.log('Wrote web/src/lib/database.types.ts');
}
